return {
    mod_name = { en = "Interrogator Randall" },
    mod_description = { en = "Reports ammo, grenade pickups, Medicae, Med Stimm, Daemonhost, barrel and Poxburster incidents to real mission chat. Includes self-damage, downs, and possible ledge deaths." },
    group_ammo = { en = "Ammo" },
    group_ammo_description = { en = "Ammo has independent live pickup, player breakdown, and team-total switches. Waste slider remains in its own category." },
    group_grenades = { en = "Grenade Pickups" },
    group_grenades_description = { en = "Grenades have independent live pickup, player breakdown, and team-total switches. Only physical grenade-box pickups count." },
    group_barrels = { en = "Barrels" },
    group_barrels_description = { en = "Barrels have independent live explosion, detonator breakdown, and team-total switches." },
    group_poxbursters = { en = "Poxbursters" },
    group_poxbursters_description = { en = "Poxbursters have independent live explosion, trigger breakdown, and team-total switches." },
    group_medicae = { en = "Medicae Stations" },
    group_medicae_description = { en = "Medicae Stations have independent live use, player breakdown, and team-total switches; percentages are estimates." },
    group_med_stimm = { en = "Med Stimms" },
    group_med_stimm_description = { en = "Green Med Stimms have independent live use, injector-recipient breakdown, and team-total switches; percentages are estimates." },
    group_daemonhost = { en = "Daemonhosts / Gormaggoth" },
    group_daemonhost_description = { en = "One switch for ordinary Daemonhost awakening and hostility, and Gormaggoth hostile-spawn reports. There is no end-of-mission summary for these." },
    group_waste_sliders = { en = "Waste Threshold Sliders (Live Reports Only)" },
    group_waste_sliders_description = { en = "Adjust the minimum wasted percentage needed for a LIVE Ammo, Grenade, Medicae, or Med Stimm message. These sliders do NOT filter or change end-of-mission summaries. Lower = more live messages; higher = fewer." },
    report_ammo = { en = "Report Ammo Pickups in Chat" },
    report_ammo_tooltip = { en = "ON = Show individual ammo pickup reports in Strike Team chat when the wasted-ammo percentage meets the Ammo waste slider. OFF = Hide live ammo pickup reports. This does NOT disable the separate end-of-mission Ammo Waste Summary." },
    report_end_ammo_team_total = { en = "End-of-Mission Ammo Team Total" },
    report_end_ammo_team_total_tooltip = { en = "ON: At mission end, show ONLY the weighted team percentage of picked-up ammo wasted across all observed ammo pickups. This includes tracked pickups from teammates who disconnect. No pickup means no team-total message. OFF: Hide this team's TOTAL line. Does not disable the per-player end-of-mission breakdown, live reports, or waste slider. Tracking continues while any report option in this category is ON." },
    report_end_ammo_summary = { en = "End-of-Mission Ammo Player Breakdown" },
    report_end_ammo_summary_tooltip = { en = "ON: At mission end, show each player's observed picked-up ammo waste percentage (weighted by ammo offered). OFF: Hide ONLY the player-by-player lines. The independent Ammo Team Total and live reports still work." },
    minimum_waste_to_report = { en = "Ammo: Minimum Waste to Show in Chat (%%)" },
    minimum_waste_to_report_tooltip = { en = "WHAT THIS SLIDER DOES: Filters ammo pickup messages in team chat. It does NOT change how much ammo players receive. Waste = the part of the pickup the player could not carry.\n\n0%% = Show every detected pickup, including 0%% waste.\n50%% = Show only pickups wasting HALF or more.\n100%% = Show only completely wasted pickups.\n\nEXAMPLE: At 50%%, a 40%%-wasted pickup is HIDDEN; a 60%%-wasted pickup is REPORTED.\n\nLOWER number = MORE chat messages. HIGHER = FEWER.\nSuggested starting value: 50%%. End-of-mission ammo summaries are separate." },
    report_grenades = { en = "Report Grenade Pickups in Chat" },
    report_grenades_tooltip = { en = "ON: Report successful physical grenade-box pickups in Strike Team chat when estimated wasted grenade capacity meets the Grenade waste slider. OFF: Hide the live grenade reports; the independent mission-end Grenade Summary can remain ON. Grenade abilities that generate charges over time are not pickups and are not included." },
    report_end_grenade_team_total = { en = "End-of-Mission Grenades Team Total" },
    report_end_grenade_team_total_tooltip = { en = "ON: At mission end, show ONLY the weighted team percentage of grenade-refill capacity wasted across all confirmed grenade-box pickups. This is an estimate of wasted charge capacity, not the number of grenades thrown. No pickup means no team-total message. OFF: Hide this team's TOTAL line. Does not disable the per-player end-of-mission breakdown, live reports, or waste slider. Tracking continues while any report option in this category is ON." },
    report_end_grenade_summary = { en = "End-of-Mission Grenade Player Breakdown" },
    report_end_grenade_summary_tooltip = { en = "ON: At mission end, show each player's estimated grenade refill waste percentage across recorded pickups. OFF: Hide ONLY the player-by-player lines. The separate Grenades Team Total and live pickup reports remain independent." },
    minimum_grenade_waste_to_report = { en = "Grenades: Minimum Waste to Show in Chat (%%)" },
    minimum_grenade_waste_to_report_tooltip = { en = "Only filters LIVE grenade pickup messages; it does not affect end-of-mission grenade waste totals. Wasted grenade capacity = charge capacity offered but already occupied before pickup. 0%% shows every confirmed pickup, 50%% shows half or more estimated waste, and 100%% only completely wasted capacity. Exact amounts depend on the player's equipped grenade ability. Suggested: 50%%." },
    report_medicae = { en = "Report Medicae Station Usage" },
    report_medicae_tooltip = { en = "ON: Send a message in Strike Team chat when a Medicae station use is detected and its estimated unused HP healing reaches the Medicae slider threshold. Shows the player and healing/corruption information when measurable.\n\nOFF: Hide individual station messages. The end-of-mission Medicae summary still tracks uses if its separate switch is ON.\n\nThe waste estimate is unused HP healing capacity, NOT wasted Medicae charges. Clearing corruption can still be worthwhile." },
    minimum_medicae_waste_to_report = { en = "Medicae: Minimum Unused Healing to Show (%%)" },
    minimum_medicae_waste_to_report_tooltip = { en = "WHAT THIS SLIDER DOES: Filters Medicae station messages by ESTIMATED unused HP healing. It does NOT measure wasted station charges. Corruption removal can still make a use worthwhile.\n\n0%% = Show every detected successful station use.\n50%% = Show only uses with HALF or more estimated healing capacity unused.\n100%% = Show only uses with no HP recovery observed (100%% unused).\n\nEXAMPLE: If max HP is 100 and a station restores 20 HP, the estimate is 80%% unused: it REPORTS at 50%%.\n\nLOWER = MORE messages. HIGHER = FEWER.\nSuggested: 0%% to track every use; 50%% for fewer messages." },
    report_med_stimm = { en = "Report Med Stimm (Health Booster) Usage" },
    report_med_stimm_tooltip = { en = "ON: Report detected uses of GREEN Med Stimms in Strike Team chat when the estimated unused healing allowance reaches the Med Stimm slider threshold. The report shows the recipient, healing and corruption restored, and the injector when identified.\n\nOFF: Hide individual injection messages. The end-of-mission Med Stimm summary still tracks confirmed uses if its separate switch is ON.\n\nOther Stimm colors are not included. Some remote injections cannot be verified." },
    minimum_med_stimm_waste_to_report = { en = "Med Stimm: Minimum Waste to Show in Chat (%%)" },
    minimum_med_stimm_waste_to_report_tooltip = { en = "WHAT THIS SLIDER DOES: Filters green Med Stimm messages by how much of its healing allowance went unused. The allowance is the greater of 25%% max HP or one wound segment. Healing and corruption removal both count.\n\n0%% = Show every use the mod can confirm, even with no waste.\n50%% = Show only injections wasting HALF or more.\n100%% = Show only confirmed injections restoring no HP or corruption.\n\nEXAMPLE: A 25-HP allowance restoring 10 HP wastes 60%%, so it REPORTS at 50%%.\n\nLOWER = MORE messages. HIGHER = FEWER.\nSuggested starting value: 50%%. Uses the mod cannot verify may not appear." },
    report_daemonhost = { en = "Report Daemonhost Awakening & Hostility" },
    report_daemonhost_tooltip = { en = "Send one line on initial awakening (including harmless alerts) and a second on hostility identifying the combat trigger and first attack target. Attribution may be estimated." },
    report_barrels = { en = "Report Barrels" },
    report_barrels_tooltip = { en = "ON: Send live Strike Team chat reports when explosive or fire barrels cause observable incidents, including HP/Toughness damage and knockbacks, with the detonator named when identifiable. Explosion events with no observed player effects require the separate harmless-explosions setting.\n\nOFF: Hide live Barrel messages. The independent End-of-Mission Barrel Damage Summary can stay ON and still track observed damage. Known self-damage is excluded from teammates' damage totals." },
    report_poxbursters = { en = "Report Poxbursters" },
    report_poxbursters_tooltip = { en = "ON: Send live Strike Team chat reports when Poxbursters explode and cause observable incidents, including HP/Toughness damage and knockbacks, with the trigger named when identifiable. Explosion events with no observed player effects require the separate harmless-explosions setting.\n\nOFF: Hide live Poxburster messages. The independent End-of-Mission Poxburster Damage Summary can stay ON and still track observed damage. Unverified causes are not assigned to a player." },
    report_end_barrel_team_total = { en = "End-of-Mission Barrels Team Total" },
    report_end_barrel_team_total_tooltip = { en = "ON: At mission end, show ONLY the total observed HP and Toughness damage caused by barrels to players, excluding damage to the known detonator. This total can appear without any per-detonator breakdown. OFF: Hide this team's TOTAL line. Does not disable the per-player end-of-mission breakdown, live reports, or waste slider. Tracking continues while any report option in this category is ON." },
    report_end_barrel_summary = { en = "End-of-Mission Barrel Detonator Breakdown" },
    report_end_barrel_summary_tooltip = { en = "ON: Show end-of-mission barrel damage broken down by identified detonator, with Unattributed when unknown. OFF: Hide the per-detonator breakdown. The separate Barrel Team Total and live Barrel reporting are unaffected." },
    report_end_poxburster_team_total = { en = "End-of-Mission Poxbursters Team Total" },
    report_end_poxburster_team_total_tooltip = { en = "ON: At mission end, show ONLY the total observed HP and Toughness damage caused by Poxburster explosions to players, excluding known self-damage. This total can appear without any per-trigger breakdown. OFF: Hide this team's TOTAL line. Does not disable the per-player end-of-mission breakdown, live reports, or waste slider. Tracking continues while any report option in this category is ON." },
    report_end_poxburster_summary = { en = "End-of-Mission Poxburster Trigger Breakdown" },
    report_end_poxburster_summary_tooltip = { en = "ON: Show end-of-mission Poxburster damage broken down by identified trigger or self-detonations when attribution is unavailable. OFF: Hide the per-trigger breakdown. The separate Poxburster Team Total and live reports are unaffected." },
    report_end_medicae_team_total = { en = "End-of-Mission Medicae Team Total" },
    report_end_medicae_team_total_tooltip = { en = "ON: At mission end, show ONLY the weighted team percentage of estimated unused Medicae healing capacity across confirmed uses. Corruption removal can justify a use; this does not measure wasted station charges. OFF: Hide this team's TOTAL line. Does not disable the per-player end-of-mission breakdown, live reports, or waste slider. Tracking continues while any report option in this category is ON." },
    report_end_medicae_summary = { en = "End-of-Mission Medicae Player Breakdown" },
    report_end_medicae_summary_tooltip = { en = "ON: Show each Medicae user's estimated healing waste percentage at mission end. OFF: Hide the player breakdown. The separate Medicae Team Total and live usage reports are unaffected." },
    report_end_med_stimm_team_total = { en = "End-of-Mission Med Stimm Team Total" },
    report_end_med_stimm_team_total_tooltip = { en = "ON: At mission end, show ONLY the weighted team percentage of unused green Med Stimm healing allowance across measurable injections. Confirmed injections without reliable healing measurements are excluded from the percentage. OFF: Hide this team's TOTAL line. Does not disable the per-player end-of-mission breakdown, live reports, or waste slider. Tracking continues while any report option in this category is ON." },
    report_end_med_stimm_summary = { en = "End-of-Mission Med Stimm Recipient Breakdown" },
    report_end_med_stimm_summary_tooltip = { en = "ON: Show each Med Stimm injector-to-recipient pair's estimated healing waste percentage at mission end, including measured uses and separate unmeasured injections. OFF: Hide the per-pair breakdown. The separate Med Stimm Team Total and live usage reports are unaffected." },
    report_toughness = { en = "Include Toughness Damage" },
    report_toughness_tooltip = { en = "Include Toughness loss and breakage in reports." },
    report_harmless_explosions = { en = "Report Explosions Without Player Damage" },
    report_harmless_explosions_tooltip = { en = "Also report barrel and Poxburster explosions without known player effects (may be noisy)." },
    explosive_fire_barrel = { en = "Fire Barrel" },
    explosive_explosion_barrel = { en = "Explosive Barrel" },
    explosive_common = { en = "Barrel" },
    diagnostic_logging = { en = "Diagnostic Logging (Console Only)" },
    diagnostic_logging_tooltip = { en = "ON: Write extra troubleshooting lines to your LOCAL Darktide console log (Medicae actions, Daemonhost states, and confirmed barrel ledge deaths). It does NOT send extra Strike Team chat messages or change waste calculations.\n\nOFF: Stops these extra diagnostic lines. Recommended for normal play; turn ON temporarily when investigating missing or incorrect reports and sharing a log." },
}
